<?php if ($opcion == 1){ ?>
  <script>
    function selectMarcados(form1)
    {
      var username="";
      var id="";
      var selected = [];
      jQuery('.check_').each(function() {
        if (jQuery(this).is(":checked")) {
          var id = jQuery(this).attr('value');
          var nomb = jQuery("#"+jQuery(this).attr('name').replace('marca', 'nomb')).val();                    
          var avatar = '<?php echo $avatar; ?>';
          var preload_data = {id: id, text: nomb , img: avatar};
          selected.push(preload_data);    
        }
      });
      //************************************************************************
      updateJSON(selected);
      parent.jQuery.CloseModalSIMAD();
    }

    function updateJSON(json){
        var responses = json;
        if(responses != null){
          var xselect2 = parent.jQuery("#<?php echo $campoText; ?>").data('select2');
          if(xselect2 != null){
            var oldjson = parent.jQuery("#<?php echo $campoText; ?>").select2('data');
          }
          //********************************************************************
          var text_name = parent.jQuery("#<?php echo $campoText; ?>").val().split(",");
          var idold = parent.jQuery("#<?php echo $campoId; ?>").val().split(",");          
          idold = jQuery.grep(idold, function(n){ return (n); });
          text_name = jQuery.grep(text_name, function(n){ return (n); });
          //avatar = jQuery.grep(avatar, function(n){ return (n); });
          //********************************************************************
          jQuery.each(json, function() {
              idold.push(this.id);
              text_name.push(this.text);
          });
          //********************************************************************
          parent.jQuery("#<?php echo $campoId; ?>").val(idold.join(","));
          //********************************************************************
          if(xselect2 != null){
            var data_selected = oldjson.concat(json);
            parent.jQuery("#<?php echo $campoText; ?>").select2('data', data_selected).trigger("change");
          }else{
            parent.jQuery("#<?php echo $campoText; ?>").val(text_name.join(","));
          }        
        }
    }

    jQuery("#selectall").click(function(){
        jQuery.ajax({
            type: "POST",
            url: "selectAllUser?<?php echo $parametros; ?>",        
            success: function(request,data){
              updateJSON(request);
              javascript:parent.jQuery.CloseModalSIMAD();
            },
            error: function(){
                alert("failure");
            }
        });
    });
  </script>
<?php } ?>
